INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('e44eb637-79e2-43a2-a867-5d3a06bca338','6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f',3.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('e44eb637-79e2-43a2-a867-5d3a06bca338','6fbf39ae-6b19-4182-b4c2-6a8d25c86c0f',$$Johnson's homelessness approach is "Treatment First, Housing Second," prioritizing compassionate medical care before stable housing — a treatment-led variant that differs from a pure Housing First model.$$,ARRAY['https://www.neighbors4faye.com/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('e44eb637-79e2-43a2-a867-5d3a06bca338','669cac97-66a6-4087-b036-936fbe62efb3',2.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('e44eb637-79e2-43a2-a867-5d3a06bca338','669cac97-66a6-4087-b036-936fbe62efb3',$$Johnson is committed to ensuring every family has the opportunity to own a home and to collaborating with landlords and residents to keep rents manageable, a pro-housing-access position.$$,ARRAY['https://www.neighbors4faye.com/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('e44eb637-79e2-43a2-a867-5d3a06bca338','fb25c1ac-91cc-49bf-8afc-c7fa22ef45e4',2.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
